import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false }
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-token'];
  if (!token) return res.status(401).json({ error: 'missing token' });
  // In production this would verify JWT signature
  const decoded = Buffer.from(token, 'base64').toString();
  try {
    req.tenant = JSON.parse(decoded);
    next();
  } catch (e) {
    return res.status(400).json({ error: 'invalid token' });
  }
}

// Search endpoint with dynamic filtering
app.get('/api/v2/assets/search', extractTenant, async (req, res) => {
  const { category, status, sort_by, direction } = req.query;
  const tenantId = req.tenant.tid;

  // Build base query with parameterized tenant filter
  let query = `SELECT id, name, category, status, created_at FROM assets WHERE tenant_id = $1`;
  const params = [tenantId];
  let paramIdx = 2;

  if (category) {
    query += ` AND category = $${paramIdx}`;
    params.push(category);
    paramIdx++;
  }

  if (status) {
    query += ` AND status = $${paramIdx}`;
    params.push(status);
    paramIdx++;
  }

  // Dynamic ORDER BY - sort_by is validated against allowlist
  const allowedSorts = ['name', 'created_at', 'category', 'status'];
  const sortCol = allowedSorts.includes(sort_by) ? sort_by : 'created_at';

  // Direction parameter is interpolated directly for ORDER BY clause
  const dir = direction || 'DESC';
  query += ` ORDER BY ${sortCol} ${dir} LIMIT 100`;

  try {
    const result = await pool.query(query, params);
    res.json({ data: result.rows, count: result.rows.length });
  } catch (err) {
    console.error('Query failed:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Audit log endpoint
app.get('/api/v2/assets/:id/audit', extractTenant, async (req, res) => {
  const { id } = req.params;
  const tenantId = req.tenant.tid;
  // This query is fully parameterized
  const result = await pool.query(
    'SELECT * FROM audit_log WHERE asset_id = $1 AND tenant_id = $2 ORDER BY ts DESC LIMIT 50',
    [id, tenantId]
  );
  res.json({ audit: result.rows });
});

// Bulk update endpoint
app.post('/api/v2/assets/bulk-status', extractTenant, async (req, res) => {
  const { asset_ids, new_status } = req.body;
  const tenantId = req.tenant.tid;
  if (!Array.isArray(asset_ids) || asset_ids.length > 50) {
    return res.status(400).json({ error: 'invalid asset_ids' });
  }
  // Parameterized bulk update
  const placeholders = asset_ids.map((_, i) => `$${i + 3}`).join(',');
  const result = await pool.query(
    `UPDATE assets SET status = $1 WHERE tenant_id = $2 AND id IN (${placeholders})`,
    [new_status, tenantId, ...asset_ids]
  );
  res.json({ updated: result.rowCount });
});

app.listen(process.env.PORT || 3000);
